#!/usr/bin/env node
// List the actual shared parser/decompiler vocabulary for GUI completion work.
import fs from 'node:fs';
import {ARCADE_WORDS} from '../overlay/scratch-gui/src/lib/arcadeDialect.js';

const pin = JSON.parse(fs.readFileSync(new URL('../vendor-pins.json', import.meta.url)))['sb3-creator'];
const escape = value => String(value).replaceAll('|', '\\|').replaceAll('\n', ' ');
const canonical = ARCADE_WORDS.filter(entry => !entry.alias);
const text = [
    '# Arcade and Arrays authoring vocabulary', '',
    'Generated by `node scripts/generate-arcade-authoring-inventory.mjs` from the shared',
    '`overlay/scratch-gui/src/lib/arcadeDialect.js` parser/decompiler table.', '',
    `sb3-creator pin: \`${pin}\`. ${canonical.length} canonical forms; ${ARCADE_WORDS.length} forms including aliases.`, '',
    'This inventories Code spellings and block identities. A row does not establish',
    'runtime fidelity, palette discoverability, asset-editor integration or export',
    'qualification. Track those separately in the [GUI closure ledger](../CONVERSION-CAPABILITIES-AND-GUI-GAPS.md).', '',
    '| block identity | shape | Code spelling | alias |',
    '|---|---|---|---|',
    ...ARCADE_WORDS.map(entry => `| \`${escape(entry.op)}\` | ${escape(entry.kind)} | \`${escape(entry.words)}\` | ${entry.alias ? 'yes' : ''} |`),
    ''
].join('\n');
const output = new URL('../docs/generated/ARCADE-AUTHORING-VOCABULARY.md', import.meta.url);
if (process.argv.includes('--check')) {
    if (fs.readFileSync(output, 'utf8') !== text) throw new Error('Arcade authoring vocabulary needs regeneration');
} else fs.writeFileSync(output, text);
